/* Player-facing explanations of the existing verified N26 scenario entries. */
(function(){'use strict';
const st=(en,ko,bodyEn,bodyKo)=>({title:[en,ko],body:[bodyEn,bodyKo]});
const guides={
 'turf-war':{summary:['From round 3 at the End-phase check: within 9 inches of the centre, you need at least one qualifying model and the opponent must have none. Ignore Seriously Injured/Damaged models.','3라운드부터 종료 단계에 중앙 9인치 안의 유효 모델이 내 쪽 1개 이상·상대 0개면 승리합니다. 중상·중손상 모델은 세지 않습니다.'],steps:[st('Wait for the check','확인 시점을 기다리기','Use the victory check in the End phase, from round 3. Entering the area during an activation does not immediately win.','3라운드부터 종료 단계의 승리 확인 때 판단합니다. 활성화 중 원 안에 들어갔다고 즉시 이기지는 않습니다.'),st('Count the right models','중앙에서 셀 모델 고르기','Check models within 9 inches of the battlefield centre. Ignore Seriously Injured and Seriously Damaged models for this condition.','전장 중심 9인치 안의 모델을 확인합니다. 이 조건에서는 중상·중손상 모델을 무시합니다.'),st('Check both sides','양쪽이 있는지 확인하기','Only A there: A wins. Only B: B wins. Both there, or neither there: this central condition does not decide a winner.','A만 있으면 A 승리, B만 있으면 B 승리입니다. 양쪽 다 있거나 아무도 없으면 중앙 조건으로 승자가 정해지지 않습니다.')],diagram:'turf',example:['Two A models and one B model are in the area: no central victory, even though A has more. If B’s only model there is Seriously Injured, ignore it and A meets the condition.','원 안에 A 2개·B 1개가 있으면 A가 더 많아도 중앙 승리가 아닙니다. 원 안의 B 모델이 중상인 모델 1개뿐이라면 그 모델은 제외하므로 A가 조건을 충족합니다.'],caution:['The central area and the whole battlefield are different. A model outside 9 inches can still be on the battlefield.','중앙 원 안과 전장 전체를 구분하세요. 9인치 밖의 모델도 전장에는 남아 있을 수 있습니다.'],links:['n26-core-model-statuses','n26-core-measurement']},
 'king-of-the-hive':{summary:['Control the one central objective at the End-phase check to gain 1 VP. Reach 3 VP to win.','중앙 목표 1개를 종료 단계의 승리 확인 때 통제하면 1VP를 얻습니다. 먼저 3VP에 도달하면 승리합니다.'],steps:[st('Set up','목표 놓기','Place one objective at the battlefield centre.','전장 중심에 목표 1개를 놓습니다.'),st('Control, then score','통제 확인 후 득점','At the End-phase victory check, the controlling player gains 1 VP. Read the shared objective-control condition below.','종료 단계 승리 확인 때 통제한 쪽이 1VP를 얻습니다. 통제 조건은 아래의 공통 설명을 확인하세요.'),st('Reach the target','3VP 도달하기','Keep a running VP total. The first player to reach 3 VP wins.','VP를 누적해 기록합니다. 먼저 3VP가 되면 승리합니다.')],diagram:'one-objective',example:['A has 2 VP. At the next End-phase check A controls the central objective: 2 + 1 = 3 VP, so A wins. Merely moving onto it has not scored yet.','A가 2VP인 상태에서 다음 종료 단계에 중앙 목표를 통제했다면 2 + 1 = 3VP로 승리합니다. 이동해서 도착한 순간에는 아직 득점한 것이 아닙니다.'],control:true,links:['n26-core-objectives']},
 'tunnel-clash':{summary:['There are three objectives. Controlling two at the check gives 1 VP; reach 3 VP to win.','목표는 총 3개입니다. 승리 확인 때 2개를 통제하면 1VP이며, 먼저 3VP가 되면 승리합니다.'],steps:[st('Place three objectives','목표 3개 놓기','Place one at the centre. Starting with the roll-off winner, each player places one more. Keep each at least 6 inches from other objectives and battlefield edges.','중앙에 1개를 놓고 롤오프 승자부터 각자 1개씩 더 놓습니다. 다른 목표와 전장 가장자리에서 각각 최소 6인치를 띄웁니다.'),st('Count control','통제한 목표 수 세기','In the End-phase victory check, controlling two objectives earns 1 VP.','종료 단계 승리 확인 때 목표 2개를 통제하면 1VP를 얻습니다.'),st('Add VP','승점 누적하기','First to 3 VP wins. Two controlled objectives do not mean 2 VP from this condition.','먼저 3VP가 되면 승리합니다. 이 조건에서 목표 2개 통제는 2VP가 아니라 1VP입니다.')],diagram:'three-objectives',example:['A controls objectives 1 and 2; B controls 3. A gains 1 VP in that check. If A started at 2 VP, the new total is 3 and A wins.','A가 목표 1·2를, B가 목표 3을 통제했다면 해당 확인에서 A가 1VP를 얻습니다. A의 기존 승점이 2VP였다면 합계 3VP로 승리합니다.'],control:true,links:['n26-core-objectives']},
 'object-lesson':{summary:['At the End phase, total VP from enemy models taken Out of Action that round. Some targets and actions add bonuses.','종료 단계에 그 라운드 적 모델을 OOA로 만든 결과를 VP로 합산합니다. 대상 종류와 사용 행동에 따라 보너스가 붙습니다.'],steps:[st('Start with 1','OOA마다 기본 1VP','Each enemy model taken Out of Action that round gives 1 VP. Seriously Injured alone is not OOA.','그 라운드 OOA가 된 적 모델마다 1VP입니다. 중상만 입힌 것은 OOA가 아닙니다.'),st('Add bonuses','보너스 더하기','Add 1 VP if the target is a Leader, Champion or Brute. Add another 1 if OOA was caused by Fight, Coup de Grace or Sabotage.','대상이 리더·챔피언·브루트라면 +1VP, 파이트·쿠 드 그라스·사보타주로 OOA였다면 추가 +1VP입니다.'),st('Check the totals','10VP와 동시 도달 확인','First to 10 VP wins. If both players reach at least 10 VP in the check, it is a draw.','먼저 10VP에 도달하면 승리합니다. 확인 결과 양쪽 모두 10VP 이상이면 무승부입니다.')],diagram:'vp-formula',example:['An ordinary enemy taken OOA by shooting gives 1 VP. A Champion taken OOA by Fight gives 1 base + 1 target bonus + 1 action bonus = 3 VP.','일반 적을 사격으로 OOA로 만들면 1VP입니다. 챔피언을 파이트로 OOA로 만들면 기본 1 + 대상 보너스 1 + 행동 보너스 1 = 3VP입니다.'],caution:['These are mission VP, not XP. Count this round’s qualifying OOA results without scoring an earlier round again.','이 계산은 미션 승점 VP이며 경험치 XP와 다릅니다. 그 라운드의 해당 OOA 결과를 세고 이전 라운드 결과를 다시 득점하지 않습니다.'],links:['n26-core-model-statuses','n26-core-action-coup-de-grace']},
 'flank-em':{summary:['Control both opposing objectives at the End phase for 1 VP. Reach 3 VP to win.','종료 단계에 양쪽 목표를 모두 통제하면 1VP를 얻습니다. 먼저 3VP가 되면 승리합니다.'],steps:[st('Mirror the positions','마주 보는 목표 놓기','The attacker chooses an edge and places an objective 6 inches inward from its midpoint. The defender places one in the mirrored position at the opposite edge.','공격자가 가장자리를 고르고 그 중앙에서 전장 안쪽 6인치에 목표를 놓습니다. 방어자는 반대 가장자리의 같은 위치에 놓습니다.'),st('Control both','두 곳 모두 통제하기','At the End phase, controlling both objectives gives 1 VP. Controlling only one does not meet this condition.','종료 단계에 목표 2개를 모두 통제해야 1VP입니다. 한 곳만 통제하면 이 조건을 충족하지 못합니다.'),st('Accumulate','3VP 누적하기','Keep the VP earned at each check; the first player to 3 VP wins.','확인 때 얻은 VP를 누적하며 먼저 3VP가 되면 승리합니다.')],diagram:'opposite-objectives',example:['A controls the near objective but B controls the far one: A has not scored this condition. If A controls both at a later check, A gains 1 VP, not 2.','A가 가까운 목표만, B가 먼 목표를 통제하면 A는 이 조건으로 득점하지 못합니다. 나중에 A가 둘 다 통제하면 2VP가 아니라 1VP를 얻습니다.'],control:true,links:['n26-core-objectives']},
 'burn-them-out':{summary:['Go into the enemy deployment zone and control your placed objectives. Each removed objective gives 1 VP; the target is 2 VP.','상대 배치 구역에 놓은 목표를 통제하는 미션입니다. 제거한 목표마다 1VP를 얻으며 목표 승점은 2VP입니다.'],steps:[st('Place the targets','상대 구역에 3개씩 놓기','Starting with the defender, alternate placing three objectives each in the enemy deployment zone. Keep them 6 inches apart if possible.','방어자부터 번갈아 상대 배치 구역에 목표를 각자 3개씩 놓습니다. 가능하면 목표끼리 6인치를 띄웁니다.'),st('Control and remove','통제 후 제거하기','At the End phase, a controlled objective in the enemy zone is removed for 1 VP.','종료 단계에 상대 구역의 목표를 통제하면 그 목표를 제거하고 1VP를 얻습니다.'),st('Check 2 VP','2VP와 무승부 확인','First to 2 VP wins. If both sides reach at least 2 VP, draw. Removed objectives cannot be scored again.','먼저 2VP면 승리하지만 양쪽 모두 2VP 이상이면 무승부입니다. 이미 제거한 목표를 다시 득점하지 않습니다.')],diagram:'enemy-zone-objectives',example:['A already has 1 VP. A controls and removes another objective in B’s zone: A reaches 2 VP. Check whether B also reached 2 before declaring the result.','A가 1VP인 상태에서 B 구역의 목표 하나를 더 통제·제거하면 2VP입니다. 결과를 정하기 전에 B도 2VP에 도달했는지 함께 확인합니다.'],control:true,links:['n26-core-objectives']}
};
for(const [key,gap,en,ko]of [['sniping-range',12,'Sniping Range','스나이핑 레인지'],['face-off',9,'Face Off','페이스 오프'],['stand-off',6,'Stand Off','스탠드 오프']])guides[key]={summary:[`Deploy from opposite edges, stopping ${gap} inches short of the central line on each side.`,`서로 반대편 가장자리에서 배치하되 중앙선 양쪽 ${gap}인치 구간에는 배치하지 않습니다.`],steps:[st('Choose the edges','가장자리 정하기','The roll-off winner picks an edge; the opponent uses the opposite edge.','롤오프 승자가 가장자리를 고르고 상대는 반대쪽을 사용합니다.'),st('Mark the central gap','중앙 빈 구간 표시',`Mark ${gap} inches from the central line towards each player.`,`중앙선에서 각 플레이어 쪽으로 ${gap}인치씩 경계를 표시합니다.`),st('Deploy outside the gap','자기 쪽 배치 구역 사용','Deploy between your own battlefield edge and that boundary.','자기 전장 가장자리와 표시한 경계 사이에 배치합니다.')],diagram:'opposite-zones',gap,example:[`The two deployment boundaries are ${gap*2} inches apart: ${gap} on A’s side plus ${gap} on B’s. This is not ${gap} inches measured inward from your own edge.`,`배치 경계 사이 간격은 ${gap} + ${gap} = ${gap*2}인치입니다. 자기 가장자리에서 안쪽 ${gap}인치만 재는 방식으로 읽으면 구역이 달라지므로 중앙선을 기준으로 표시하세요.`],links:['n26-core-measurement']};
guides.ambush={summary:['The defender starts near the centre; the attacker starts outside a larger central circle.','방어자는 중앙 가까이, 공격자는 더 큰 중앙 원의 바깥에서 시작합니다.'],steps:[st('Identify roles','공격자·방어자 확인','Use the battle’s attacker and defender roles.','전투에 정해진 공격자와 방어자를 확인합니다.'),st('Place the defender','방어자 배치','The defender deploys within 6 inches of the battlefield centre.','방어자는 전장 중심 6인치 이내에 배치합니다.'),st('Place the attacker','공격자 배치','The attacker deploys at least 12 inches from the centre.','공격자는 전장 중심에서 12인치 이상 떨어져 배치합니다.')],diagram:'ambush',example:['A defender 5 inches from the centre is in its zone. An attacker 10 inches from the centre is too close; at least 12 inches is required.','중심에서 5인치인 방어자는 자기 구역 안입니다. 중심에서 10인치인 공격자는 너무 가까우며 최소 12인치가 필요합니다.'],caution:['The distance is measured from the centre, not from the nearest enemy model.','이 배치 거리는 가장 가까운 적이 아니라 전장 중심을 기준으로 확인합니다.'],links:['n26-core-measurement']};
guides['free-for-all']={summary:['Use diagonally opposite quarters and stay at least 9 inches from the centre.','서로 대각선으로 마주 보는 사분면을 사용하고 중심에서 최소 9인치를 띄웁니다.'],steps:[st('Divide the field','전장을 네 구역으로 나누기','Mark the centre and divide the battlefield into quarters.','전장 중심을 표시하고 전장을 사분면으로 나눕니다.'),st('Choose opposite quarters','반대 사분면 정하기','The roll-off winner chooses a quarter; the opponent takes the opposite quarter.','롤오프 승자가 사분면을 고르고 상대는 반대 사분면을 사용합니다.'),st('Keep the centre clear','중앙에서 거리 띄우기','Deploy in your quarter at least 9 inches from the centre.','자기 사분면 안에서 중심 9인치 이상 떨어진 곳에 배치합니다.')],diagram:'quarters',example:['If A takes the upper-left quarter, B takes the lower-right. A point 7 inches from the centre is still too close even if it is in the correct quarter.','A가 왼쪽 위라면 B는 오른쪽 아래를 사용합니다. 자기 사분면이어도 중심에서 7인치인 곳은 너무 가깝습니다.'],links:['n26-core-measurement']};
guides['chance-encounter']={summary:['Each side uses two opposite corners and splits its starting crew as evenly as possible.','양쪽은 서로 마주 보는 모서리 2곳씩 사용하고 시작 크루를 최대한 균등하게 나눕니다.'],steps:[st('Choose corner pairs','모서리 두 쌍 정하기','The roll-off winner chooses a corner and its diagonal opposite. The opponent takes the other pair.','롤오프 승자가 모서리 하나와 대각선 반대 모서리를 고릅니다. 상대는 남은 두 모서리를 사용합니다.'),st('Mark the zones','각 모서리 9인치 구역 표시','Your deployment zones are within 9 inches of each of your two corners.','자기 모서리 2곳 각각의 9인치 이내가 배치 구역입니다.'),st('Split the crew','크루를 균등하게 나누기','Divide the starting crew as evenly as possible between the two zones.','시작 크루를 두 구역에 최대한 균등하게 나눠 배치합니다.')],diagram:'corners',example:['A starting crew of 7 splits 4 and 3; a crew of 8 splits 4 and 4. Do not put all 7 in just one of the two zones.','시작 크루가 7명이면 4명·3명, 8명이면 4명·4명으로 나눕니다. 두 구역 중 한 곳에만 7명을 몰아넣는 방식이 아닙니다.'],links:['n26-core-measurement']};
const crews={
 'escalating-engagement':{chosen:3,random:'D3',deck:5,example:['If D3 is 2, choose 3 then randomly draw 2 more: start with 5. Keep a separate 5-card reinforcement deck; its first arrivals are at the End phase of round 1.','D3가 2라면 직접 3명 선택 + 무작위 2명 = 5명으로 시작합니다. 증원 덱 5장은 따로 두며 첫 도착은 1라운드 종료 단계입니다.']},
 'hold-nothing-back':{chosen:10,random:0,example:['Custom (10) means choosing 10 eligible models from the roster and choosing their equipment sets. It does not create ten new models.','커스텀(10)은 참가 가능한 보유 모델 10명과 장비 세트를 직접 고른다는 뜻입니다. 새 모델 10명을 지급하는 효과가 아닙니다.']},
 patrol:{chosen:3,random:4,example:['Choose 3 first, remove those cards from the pool, then randomly draw 4 others: 7 starting models. Do not randomly draw the chosen three a second time.','먼저 3명을 고르고 그 카드를 제외한 남은 덱에서 4명을 무작위로 뽑아 총 7명으로 시작합니다. 이미 고른 3명을 다시 뽑지 않습니다.']},
 'surprise-attack':{chosen:4,random:4,defender:true,deck:7,example:['The attacker chooses 4 and randomly adds 4, starting with 8. The defender chooses 3 and keeps a separate 7-card reinforcement deck. The defender’s first D3 arrivals happen at the End phase of round 1.','공격자는 직접 4명 + 무작위 4명으로 총 8명, 방어자는 직접 고른 3명으로 시작합니다. 방어자의 증원 덱 7장은 별도이며 1라운드 종료 단계부터 D3명씩 도착합니다.']},
 'strike-force':{chosen:5,random:0,example:['Custom (5) is five models chosen by the player; it is not five randomly drawn cards. Choose an eligible equipment set for each.','커스텀(5)은 플레이어가 직접 고르는 5명이며 무작위 5장 추출이 아닙니다. 각자의 적격 장비 세트도 고릅니다.']},
 'scouting-force':{chosen:'D3',random:5,example:['If D3 is 2, choose 2 first, then randomly draw 5 from the remaining eligible cards: 7 starting models. Here the variable number belongs to the chosen part.','D3가 2라면 직접 2명을 먼저 고른 뒤 남은 적격 카드에서 무작위 5명을 뽑아 총 7명입니다. 여기서 D3는 무작위 추출 수가 아니라 직접 선택 인원입니다.']}
};
for(const [key,c]of Object.entries(crews)){const chosen=String(c.chosen),random=String(c.random);guides[key]={summary:[c.defender?'Attacker: 4 chosen + 4 random. Defender: 3 chosen, plus a separate reinforcement deck.':`${chosen} chosen${c.random?' + '+random+' random':''} for each starting crew${c.deck?'; keep reinforcements separate':''}.`,c.defender?'공격자는 직접 4명 + 무작위 4명, 방어자는 직접 3명으로 시작하고 증원은 따로 준비합니다.':`양쪽 모두 직접 ${chosen}명${c.random?' + 무작위 '+random+'명':''}으로 시작${c.deck?'하고 증원은 별도로 둡니다':''}.`],steps:[st('Use eligible models','참가 가능한 모델만 준비','Use eligible roster models. Random draws use one Model Card per model; multiple equipment-set cards do not count as multiple models.','참가 가능한 명단 모델만 사용합니다. 무작위 덱은 모델당 카드 1장이며 장비 세트 카드가 여러 장이어도 여러 모델로 세지 않습니다.'),st('Choose, then draw','직접 선택 후 무작위 추출',c.defender?'For the attacker, choose 4 then draw 4 others. The defender chooses 3.':`Choose ${chosen} first${c.random?', then randomly draw '+random+' other eligible cards':'; choose the equipment sets as permitted'}.`,c.defender?'공격자는 4명을 고른 뒤 나머지에서 4명을 뽑습니다. 방어자는 3명을 직접 고릅니다.':`먼저 ${chosen}명을 직접 고릅니다${c.random?'. 그다음 남은 적격 카드에서 '+random+'명을 무작위로 뽑습니다':'. 허용된 장비 세트도 선택합니다'}.`),...(c.deck?[st('Keep reinforcements separate','시작 크루와 증원 구분',`Prepare ${c.deck} eligible reinforcement cards outside the starting crew${c.defender?' for the defender':''}. From round 1, D3 arrive each round in the End phase, while cards remain.`,`시작 크루에 없는 적격 카드 ${c.deck}장${c.defender?'을 방어자의 증원 덱으로':'을 증원 덱으로'} 준비합니다. 1라운드부터 매 라운드 종료 단계에 남은 덱에서 D3명씩 도착합니다.`)]:[])],diagram:'crew',crew:c,example:c.example,caution:['Chosen + random is the starting crew. A reinforcement deck is not already on the battlefield, and these instructions do not recruit missing models. Apply any additional faction-specific crew rule separately.','직접 선택 + 무작위 추출이 시작 크루입니다. 증원 덱은 아직 전장에 배치된 인원이 아니며 부족한 모델을 새로 지급하지도 않습니다. 갱 고유의 추가 크루 규칙은 별도로 확인하세요.'],links:['official-003-core-crew-selection-methods',...(c.deck?['official-003-core-reinforcements']:[])]};}
const jobs={
 'stitch-em-up':{summary:['Plant evidence during Coup de Grace instead of the Strength roll-off.','쿠 드 그라스에서 힘 롤오프 대신 증거를 심는 선택을 합니다.'],steps:[st('Find the opportunity','행동·대상 조건 확인','Use Coup de Grace against a Seriously Injured enemy Fighter under that action’s normal conditions.','쿠 드 그라스의 정상 행동 조건을 만족하는 중상 적 파이터를 대상으로 합니다.'),st('Replace the roll-off','힘 대결 대신 증거 심기','Choose to plant evidence instead of resolving the Strength roll-off.','힘 롤오프를 진행하는 대신 증거를 심습니다.'),st('Complete the job','전투 종료 때 달성 확인','Planting evidence on at least one enemy during the battle completes the job, even if that model later leaves play.','전투 중 적 1명 이상에게 심었다면 그 모델이 나중에 전장을 떠나도 전투 종료 때 달성합니다.')],example:['Evidence was planted, then that target left the battlefield: the earlier evidence still counts. An ordinary Coup de Grace with no evidence planted does not fulfil this job.','증거를 심은 대상이 나중에 전장을 떠나도 심은 기록은 유효합니다. 증거를 심지 않은 일반 쿠 드 그라스만으로 이 사이드 잡을 달성한 것은 아닙니다.'],links:['n26-core-action-coup-de-grace']},
 'the-package':{summary:['Deliver the marked Fighter to the stated contact point and check from round 3.','마커를 가진 파이터를 지정 접촉 지점까지 보내고 3라운드부터 확인합니다.'],steps:[st('Assign after deployment','배치 후 운반자 지정','After both sides deploy, give the package marker to one of your deployed Fighters.','양쪽 배치 후 배치된 자기 파이터 1명에게 패키지 마커를 줍니다.'),st('Reach the destination','도착 지점에 베이스 접촉','Touch a battlefield edge in the enemy deployment zone with the carrier’s base. If that zone has no battlefield edge, use the battlefield centre.','운반자의 베이스를 상대 배치 구역에 속한 전장 가장자리와 접촉시킵니다. 그 구역에 전장 가장자리가 없다면 전장 중심을 사용합니다.'),st('Check at the right time','3라운드부터 종료 단계 확인','From round 3, at the End-phase victory check, remove the package if the contact condition is met.','3라운드부터 종료 단계 승리 확인 때 접촉 조건이 맞으면 패키지를 제거하고 달성합니다.')],example:['Reaching the correct point during round 2 is not this job’s completion check. Stay able to meet the condition when an eligible End-phase check is made.','2라운드에 도착했다고 그 순간 달성하는 것은 아닙니다. 달성 가능한 종료 단계 확인 시점에 접촉 조건을 충족해야 합니다.'],links:['n26-core-measurement']},
 'settle-a-score':{summary:['Randomly mark a deployed enemy other than the Leader; that specific model must leave play or go OOA.','배치된 적 리더 이외 모델을 무작위로 지정하고, 바로 그 대상의 OOA·퇴장을 확인합니다.'],steps:[st('Reveal the target','배치 후 대상을 공개','After deployment randomly choose a deployed enemy model other than the Leader and announce it.','배치 후 적 리더를 제외한 배치 모델 1명을 무작위로 골라 공개합니다.'),st('Track that model','지정한 모델 추적','The target must go Out of Action or leave the battlefield for any reason.','그 대상이 OOA가 되거나 이유를 불문하고 전장을 떠나야 합니다.'),st('Check the result','종료 단계에 확인','Any round’s End-phase victory check can complete the job if that target meets the condition.','어느 라운드든 종료 단계 승리 확인 때 해당 대상이 조건을 충족하면 달성합니다.')],example:['Another enemy going OOA does not substitute for the named target. The named target leaving by a route other than an attack still meets the stated departure condition.','다른 적을 OOA로 만들어도 지정 대상 대신으로 계산하지 않습니다. 지정 대상은 공격 이외의 이유로 떠나도 명시된 퇴장 조건을 충족합니다.'],links:['n26-core-model-statuses']},
 'crippling-strike':{summary:['At least half the enemy models still on the battlefield must be Seriously Injured/Damaged or Engaged.','전장에 남은 적 모델의 절반 이상이 중상·중손상 또는 교전 상태여야 합니다.'],steps:[st('Use the current total','전장에 있는 적 수 세기','At the End-phase victory check, count enemy models currently on the battlefield.','종료 단계 승리 확인 때 현재 전장에 있는 적 모델 수를 셉니다.'),st('Count qualifying models once','해당 상태의 모델 수 세기','Count models that are Seriously Injured, Seriously Damaged or Engaged. A model satisfying two statuses still counts as one model.','중상·중손상·교전 중 하나 이상에 해당하는 모델을 셉니다. 두 상태에 해당해도 모델 1개로 셉니다.'),st('Meet at least half','절반 이상인지 비교','The qualifying number must be at least half of the current enemy total.','해당 모델 수가 현재 적 총수의 절반 이상이어야 합니다.')],example:['With 5 enemies on the battlefield, 3 qualifying models meet the condition; 2 do not. With 6 enemies, 3 are enough.','적이 5개 남았다면 해당 모델 3개가 필요하며 2개로는 부족합니다. 적이 6개라면 3개로 충족합니다.'],caution:['Use the current battlefield count, not the original roster size or only the uninjured models.','처음 명단 인원이나 멀쩡한 모델 수만을 분모로 쓰지 말고 현재 전장에 있는 적 총수를 사용하세요.'],links:['n26-core-model-statuses']},
 'spread-unrest':{summary:['Use Graffiti (Double) with an Active non-Beast Fighter in the required area.','지정 구역에서 비스트가 아닌 액티브 파이터로 그래피티(더블)를 수행합니다.'],steps:[st('Choose the Fighter','사용 모델 조건 확인','The model must be a friendly Active Fighter without the Beast subtype.','비스트 서브타입이 아닌 아군 액티브 파이터여야 합니다.'),st('Reach the area','상대 구역에 들어가기','Use the enemy deployment zone; if none exists, use within 6 inches of the battlefield centre.','상대 배치 구역에서 수행합니다. 상대 배치 구역이 없으면 전장 중심 6인치 이내를 사용합니다.'),st('Perform the action','그래피티 더블 수행','One Fighter performing Graffiti (Double) during the battle completes the job, even if it later leaves. Double normally costs both actions.','전투 중 1명 이상이 그래피티(더블)를 수행하면 이후 떠나도 달성합니다. 더블은 정상적으로 행동 2개를 사용합니다.')],example:['Being in the zone alone is not enough: perform Graffiti. A normal two-action activation cannot also spend one action on Move and still pay a Double cost.','구역 안에 있기만 해서는 부족하며 그래피티를 수행해야 합니다. 정상 행동 2개 중 무브에 1개를 썼다면 더블 비용 2개를 추가로 낼 수 없습니다.'],links:['n26-core-action-economy']},
 'protect-the-future':{summary:['Randomly nominate the required young Fighter after deployment and keep it on the battlefield until battle end.','배치 후 해당 파이터를 무작위로 지정하고 전투 종료까지 전장에 남게 합니다.'],steps:[st('Choose the eligible pool','후보 종류 정하기','Use a deployed Prospect. If the starting crew has no Prospect, use a Ganger. If it has neither, generate a new Side Job.','배치된 프로스펙트를 대상으로 합니다. 시작 크루에 프로스펙트가 없으면 갱어를 사용하며 둘 다 없으면 새 사이드 잡을 생성합니다.'),st('Pick randomly and reveal','무작위 지정 후 공개','Randomly select the eligible deployed Fighter after deployment and announce it.','배치 후 해당하는 배치 파이터 중 무작위로 1명을 골라 공개합니다.'),st('Remain until the end','전투 종료까지 전장에 남기기','The selected Fighter must still be on the battlefield when the battle ends.','선택한 파이터가 전투 종료 때 전장에 남아 있으면 달성합니다.')],example:['Keeping some other Prospect safe is not a substitute if the nominated Fighter has left. If it is still on the battlefield at battle end, check the stated remain-on-field condition.','지정 파이터가 떠났다면 다른 프로스펙트가 안전하게 남아 있어도 대신 계산하지 않습니다. 지정 파이터가 종료 때 전장에 남았는지 확인하세요.'],links:['n26-core-model-statuses']}
};
for(const [key,value]of Object.entries(jobs))guides[key]={...value,diagram:'job'};
window.MMScenarioGuideData=guides;
})();
